import os, re, json, sqlite3, hashlib, secrets, threading
from datetime import datetime, timezone
from flask import Flask, request, jsonify, g, send_from_directory
DB='/app/huddle.db'
NODE=int(os.environ.get('NODE_ID','0'))
app=Flask(__name__)
def now(): return datetime.now(timezone.utc).isoformat().replace('+00:00','Z')
def db():
    if 'db' not in g:
        g.db=sqlite3.connect(DB, check_same_thread=False)
        g.db.row_factory=sqlite3.Row
    return g.db
@app.teardown_appcontext
def close(e):
    x=g.pop('db',None)
    if x: x.close()
def init():
    c=sqlite3.connect(DB); c.executescript('''
    CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT "UTC",avatar_url TEXT DEFAULT "",status_text TEXT DEFAULT "",status_emoji TEXT DEFAULT "");
    CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
    CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT DEFAULT "open");
    CREATE TABLE IF NOT EXISTS members(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
    CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT "",is_archived INTEGER DEFAULT 0);
    CREATE TABLE IF NOT EXISTS channel_members(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
    CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0,event_id INTEGER);
    CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,PRIMARY KEY(message_id,user_id,emoji));
    '''); c.commit(); c.close()
init()
def out(x,status=200): return jsonify(x),status
def auth():
    t=request.headers.get('Authorization','')
    if t.startswith('Bearer '):
        r=db().execute('SELECT user_id FROM tokens WHERE token=?',(t[7:],)).fetchone()
        if r:return r['user_id']
    return None
def need():
    u=auth()
    if not u: return None,(jsonify(error='unauthorized'),401)
    return u,None
def userobj(r):
    return {k:r[k] for k in ['id','username','display_name','timezone','avatar_url','status_text','status_emoji']}
def chan(r): return {k:(bool(r[k]) if k in ('is_private','is_dm','is_archived') else r[k]) for k in ['id','workspace_id','name','is_private','is_dm','topic','is_archived']}
def msg(r):
    d=dict(r); d['author']=db().execute('SELECT * FROM users WHERE id=?',(d['author_id'],)).fetchone()
    d['author']=userobj(d['author']); d['parent_id']=d['parent_id']; d['reply_count']=db().execute('SELECT count(*) n FROM messages WHERE parent_id=? AND deleted=0',(d['id'],)).fetchone()['n']
    d['files']=[]; d['reactions']=[]
    for x in db().execute('SELECT emoji,count(*) n FROM reactions WHERE message_id=? GROUP BY emoji',(d['id'],)):
        ids=[z['user_id'] for z in db().execute('SELECT user_id FROM reactions WHERE message_id=? AND emoji=?',(d['id'],x['emoji']))]
        d['reactions'].append({'emoji':x['emoji'],'count':x['n'],'user_ids':ids})
    d.pop('deleted',None); return d
@app.route('/api/health')
def health(): return jsonify(status='ok',node_id=NODE)
@app.route('/api/auth/register',methods=['POST'])
def register():
    x=request.get_json(silent=True) or {}; u=x.get('username',''); p=x.get('password','')
    if not isinstance(u,str) or not re.fullmatch(r'[A-Za-z0-9_]+',u) or not isinstance(p,str) or len(p)<8:return out({'error':'invalid input'},400)
    try:
        c=db(); c.execute('INSERT INTO users(username,password,display_name) VALUES(?,?,?)',(u,hashlib.sha256(p.encode()).hexdigest(),x.get('display_name') or u)); c.commit()
    except sqlite3.IntegrityError:return out({'error':'duplicate'},409)
    return login_user(c.execute('SELECT * FROM users WHERE username=?',(u,)).fetchone(),201)
def login_user(r,status=200):
    t=secrets.token_urlsafe(24); db().execute('INSERT INTO tokens VALUES(?,?)',(t,r['id'])); db().commit(); return out({'user':userobj(r),'token':t},status)
@app.route('/api/auth/login',methods=['POST'])
def login():
    x=request.get_json(silent=True) or {}; r=db().execute('SELECT * FROM users WHERE username=? AND password=?',(x.get('username'),hashlib.sha256(str(x.get('password','')).encode()).hexdigest())).fetchone()
    return login_user(r) if r else out({'error':'invalid credentials'},401)
@app.route('/api/auth/me')
def me():
    u,e=need()
    if e:return e
    return out({'user':userobj(db().execute('SELECT * FROM users WHERE id=?',(u,)).fetchone())})
@app.route('/api/workspaces',methods=['GET','POST'])
def workspaces():
    u,e=need()
    if e:return e
    c=db()
    if request.method=='POST':
        x=request.get_json(silent=True) or {}; slug=x.get('slug','')
        if not re.fullmatch(r'[a-z0-9-]{2,32}',slug) or not x.get('name'):return out({'error':'invalid'},400)
        try:c.execute('INSERT INTO workspaces(slug,name,owner_id) VALUES(?,?,?)',(slug,x['name'],u)); wid=c.execute('SELECT last_insert_rowid()').fetchone()[0]; c.execute('INSERT INTO members VALUES(?,?,?)',(wid,u,'owner'));c.execute('INSERT INTO channels(workspace_id,name) VALUES(?,?)',(wid,'general'));cid=c.execute('SELECT last_insert_rowid()').fetchone()[0];c.execute('INSERT INTO channel_members VALUES(?,?)',(cid,u));c.commit()
        except sqlite3.IntegrityError:return out({'error':'duplicate'},409)
        w=dict(c.execute('SELECT * FROM workspaces WHERE id=?',(wid,)).fetchone()); w.pop('id',None); w['id']=wid
        return out({'workspace':w,'general_channel':chan(c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone())},201)
    rows=c.execute('SELECT w.* FROM workspaces w JOIN members m ON m.workspace_id=w.id WHERE m.user_id=?',(u,)).fetchall();return out({'workspaces':[dict(x) for x in rows]})
@app.route('/api/workspaces/<slug>')
def workspace(slug):
    u,e=need()
    if e:return e
    w=db().execute('SELECT * FROM workspaces WHERE slug=?',(slug,)).fetchone()
    if not w:return out({'error':'not found'},404)
    cs=db().execute('SELECT * FROM channels WHERE workspace_id=? AND is_archived=0',(w['id'],)).fetchall()
    return out({'workspace':dict(w),'channels':[chan(x) for x in cs],'read_state':{}})
@app.route('/api/workspaces/<slug>/members')
def members(slug):
    u,e=need()
    if e:return e
    w=db().execute('SELECT id FROM workspaces WHERE slug=?',(slug,)).fetchone()
    if not w:return out({'error':'not found'},404)
    return out({'members':[dict(x) for x in db().execute('SELECT user_id,role FROM members WHERE workspace_id=?',(w['id'],))]})
@app.route('/api/workspaces/<slug>/channels',methods=['POST'])
def create_channel(slug):
    u,e=need()
    if e:return e
    w=db().execute('SELECT * FROM workspaces WHERE slug=?',(slug,)).fetchone(); x=request.get_json(silent=True) or {}
    if not w:return out({'error':'not found'},404)
    if not db().execute('SELECT 1 FROM members WHERE workspace_id=? AND user_id=?',(w['id'],u)).fetchone():return out({'error':'forbidden'},403)
    if not re.fullmatch(r'[a-z0-9-]{1,32}',str(x.get('name',''))):return out({'error':'invalid'},400)
    try: db().execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w['id'],x['name'],int(bool(x.get('is_private'))),x.get('topic',''))); cid=db().execute('SELECT last_insert_rowid()').fetchone()[0];db().execute('INSERT INTO channel_members VALUES(?,?)',(cid,u));db().commit()
    except sqlite3.IntegrityError:return out({'error':'duplicate'},409)
    return out({'channel':chan(db().execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone())},201)
@app.route('/api/channels/<int:cid>/join',methods=['POST'])
def join(cid):
    u,e=need()
    if e:return e
    r=db().execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone()
    if not r:return out({'error':'not found'},404)
    db().execute('INSERT OR IGNORE INTO channel_members VALUES(?,?)',(cid,u));db().execute('INSERT OR IGNORE INTO members VALUES(?,?,?)',(r['workspace_id'],u,'member'));db().commit();return out({'channel':chan(r)})
@app.route('/api/channels/<int:cid>/messages',methods=['GET','POST'])
def messages(cid):
    u,e=need()
    if e:return e
    if not db().execute('SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?',(cid,u)).fetchone():return out({'error':'forbidden'},403)
    c=db()
    if request.method=='POST':
        x=request.get_json(silent=True) or {}; body=x.get('body')
        if not isinstance(body,str) or not body.strip():return out({'error':'empty'},400)
        r=c.execute('SELECT * FROM channels WHERE id=?',(cid,)).fetchone()
        if r['is_archived']:return out({'error':'archived'},423)
        eid=(c.execute('SELECT coalesce(max(event_id),0)+1 n FROM messages WHERE channel_id=?',(cid,)).fetchone()['n'])
        c.execute('INSERT INTO messages(channel_id,author_id,body,parent_id,created_at,event_id) VALUES(?,?,?,?,?,?)',(cid,u,body,x.get('parent_id'),now(),eid));c.commit()
        return out({'message':msg(c.execute('SELECT * FROM messages WHERE id=?',(c.execute('SELECT last_insert_rowid()').fetchone()[0],)).fetchone())},201)
    rows=c.execute('SELECT * FROM messages WHERE channel_id=? AND parent_id IS NULL AND deleted=0 ORDER BY id DESC LIMIT 200',(cid,)).fetchall();return out({'messages':[msg(x) for x in rows],'next_cursor':None})
@app.route('/api/messages/<int:mid>/replies')
def replies(mid):
    u,e=need()
    if e:return e
    rows=db().execute('SELECT * FROM messages WHERE parent_id=? AND deleted=0 ORDER BY id',(mid,)).fetchall();return out({'replies':[msg(x) for x in rows],'next_cursor':None})
@app.route('/api/messages/<int:mid>/reactions',methods=['POST'])
def react(mid):
    u,e=need()
    if e:return e
    x=request.get_json(silent=True) or {}; db().execute('INSERT OR IGNORE INTO reactions VALUES(?,?,?)',(mid,u,x.get('emoji','')));db().commit();return out({'reactions':msg(db().execute('SELECT * FROM messages WHERE id=?',(mid,)).fetchone())['reactions']})
@app.route('/')
def index(): return '<!doctype html><html><body><h1>Huddle</h1><div id="app">Huddle chat</div></body></html>'
if __name__=='__main__':
    app.run(host='127.0.0.1',port=int(os.environ.get('PORT',8000)),threaded=True)
PY
cat > /app/start.sh <<'SH'
#!/bin/sh
set -eu
[ -f /app/huddle.db ] || : > /app/huddle.db
pids=""
trap 'kill $pids 2>/dev/null || true; exit 0' TERM INT
for i in 0 1 2; do PORT=$((8000+i)) NODE_ID=$i python3 /app/server.py & pids="$pids $!"; done
wait
SH
chmod +x /app/start.sh
ls -l /app/start.sh /app/server.py /app/requirements.txt
```

